from fractions import Fraction
import re

@dataclass(frozen=True)
class Ingredient:
    quantity: Fraction
    unit: str
    name: str

_QUANTITY = re.compile(r"^(\d+(?:\s+\d+/\d+|/\d+)?|\d+/\d+)\s+(\S+)\s+(.+)$")

def parse_ingredient(line: str) -> Ingredient:
    match = _QUANTITY.fullmatch(line.strip())
    if match is None:
        raise ValueError(f"invalid ingredient line: {line!r}")
    quantity_text, unit, name = match.groups()
    parts = quantity_text.split()
    if len(parts) == 2:
        quantity = Fraction(int(parts[0])) + Fraction(parts[1])
    else:
        quantity = Fraction(parts[0])
    return Ingredient(quantity, unit, name.strip())

