def zone_for_postcode(postcode: str) -> str:
    """The 02 prefix maps to metro; unknown prefixes use standard."""
    normalized = postcode.strip().replace(" ", "")
    for prefix, zone in _ZONE_RULES:
        if normalized.startswith(prefix):
            return zone
    return "standard"

