public final class Importer {
    public record PeakReading(String patientId, Instant recordedAt, int peakBpm) {}

    public List<PeakReading> importReadings(Reader source) throws IOException {
        BufferedReader reader = source instanceof BufferedReader b ? b : new BufferedReader(source);
        if (!"patient_id,recorded_at,peak_bpm".equals(reader.readLine())) {
            throw new IOException("Unexpected CSV header");
        }
        List<PeakReading> readings = new ArrayList<>();
        String line;
        int row = 1;
        while ((line = reader.readLine()) != null) {
            row++;
            String[] fields = line.split(",", -1);
            if (fields.length != 3 || fields[0].isBlank()) {
                throw new IOException("Malformed CSV row " + row);
            }
            try {
                readings.add(new PeakReading(fields[0], Instant.parse(fields[1]),
                        Integer.parseInt(fields[2])));
            } catch (DateTimeParseException | NumberFormatException e) {
                throw new IOException("Malformed CSV row " + row, e);
            }
        }
        return List.copyOf(readings);
    }
}

