    """Return a room number for each (start, end) pair."""
    ordered = sorted(enumerate(meetings), key=lambda item: item[1][0])
    room_ends = []
    assignment = [None] * len(meetings)

    for original_index, (start, end) in ordered:
        for room_id, finish in enumerate(room_ends):
            if finish < start:
                room_ends[room_id] = end
                assignment[original_index] = room_id
                break
        else:
            room_id = len(room_ends)
            room_ends.append(end)
            assignment[original_index] = room_id

    return assignment

